class InsufficientFundsException extends Exception {
    InsufficientFundsException(String message) {
        super(message);
    }
}

class Account {
    private double balance = 100;

    void withdraw(double amount) throws InsufficientFundsException {
        if (amount > balance) {
            throw new InsufficientFundsException("need " + amount + " but only " + balance + " available");
        }
        balance -= amount;
    }
}

public class Bank {
    public static void main(String[] args) {
        Account account = new Account();
        try {
            account.withdraw(30);
            account.withdraw(500);
            System.out.println("Both withdrawals succeeded");
        } catch (InsufficientFundsException e) {
            System.out.println("Rejected: " + e.getMessage());
        }
        System.out.println("Program continues");
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public class ReadFirst {
    public static void main(String[] args) {
        try (BufferedReader reader = Files.newBufferedReader(Path.of("missing.txt"))) {
            System.out.println(reader.readLine());
        } catch (IOException e) {
            System.out.println("Could not read file: " + e.getMessage());
        }
    }
}
